/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
/// <param name="args">PrePostArgs</param>
[PreHandlerFor(classStr(InventQualityOrderValidate), methodStr(InventQualityOrderValidate, run))]
public static void InventQualityOrderValidate_Pre_run(XppPrePostArgs args)
{
    InventQualityOrderValidate qOrderValidate = args.getThis();
    InventQualityOrderTable qOrderTable;
    InventQualityOrderLine qOrderLine;

    qOrderTable = InventQualityOrderTable::find(qOrderValidate.parmQualityOrderId(), true);
    select firstonly qOrderLine order by TestSequence where qorderLine.qualityOrderId == qOrderTable.QualityOrderId;

    qOrderTable.Qty = qorderline.avaDisplayResultQty();
    qOrderTable.update();

}
